import { VERSION, DEFAULT_PROFILE, EXERCISES, BY_ID, LABELS, makePlan, isoLocalDate, summarize, validateImport, validateSession } from './core.mjs';
import { TRACKS, skillIndex, skillCompleted, stageAllowed, recordedSets, weeklyLoad, visualGuide } from './evolution.mjs';
import { DEFAULT_REMINDERS, normalizeReminders, AWARDS, gamification, calendarUrl, calendarIcs, inQuietTime } from './gamification.mjs';
import { imagesHtml, remoteImages, matchCount, bjjDiagram } from './visuals.mjs';

const STORAGE_KEY='calistenia_bjj_v1';
const content=document.getElementById('content');
const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const options=(map,value)=>Object.entries(map).map(([id,name])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(name)}</option>`).join('');
const fmtDate=(v)=>{const d=new Date((v||isoLocalDate())+'T12:00:00');return Number.isNaN(d.valueOf())?esc(v):d.toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});};
const greeting=()=>new Date().getHours()<12?'Bom dia':new Date().getHours()<18?'Boa tarde':'Boa noite';
function freshState(){return {schema:VERSION,profile:{...DEFAULT_PROFILE},history:[],workout:null,skills:{},reminders:{...DEFAULT_REMINDERS}};}
let memoryOnly=false;
function load(){try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return freshState();const v=JSON.parse(raw);if(!validateImport(v))throw Error('Dados inválidos');return {...freshState(),...v,profile:{...DEFAULT_PROFILE,...v.profile},reminders:normalizeReminders(v.reminders)};}catch(err){memoryOnly=true;return freshState();}}
let state=load(),tab='inicio',search='',filter='todos',selectedExercise=null,exerciseReturn='exercicios',selectedTrack=null,installPrompt=null,toastTimer=null;
function currentPlan(){const plan=makePlan(state.profile);const load=weeklyLoad(state.history);if(load.high&&!plan.recovery){plan.days=plan.days.slice(0,2);plan.why+=' Foram registrados vários treinos de BJJ nesta semana: considere reduzir volume e inserir recuperação.';}return plan;}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));memoryOnly=false;return true;}catch(err){memoryOnly=true;notify('Sem armazenamento local. Exporte um backup antes de sair.');return false;}}
function notify(msg){const t=document.getElementById('toast');t.textContent=msg;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',3900);}
function go(next){tab=next;selectedExercise=null;render();window.scrollTo({top:0,behavior:'instant'});}
function header(eyebrow,title,subtitle=''){return `<header class="top-section"><div class="eyebrow">${esc(eyebrow)}</div><h1 class="headline">${title}</h1>${subtitle?`<p class="lead">${subtitle}</p>`:''}</header>`;}
function section(title,body,classes=''){return `<section class="card ${classes}"><h2 class="section-title">${title}</h2>${body}</section>`;}
function chip(value){return `<span class="chip">${esc(value)}</span>`;}
function tagCat(ex){return LABELS.category[ex.category]||ex.category;}
function exIcon(ex){return ({aquecimento:'↗',forca:'◆',musculacao:'▰',mobilidade:'◌',drill:'◎',condicionamento:'◷',recuperacao:'☾'})[ex.category]||'◈';}
function exRow(ex,withButton=true){const media=remoteImages(ex);return `<div class="exercise"><div class="exicon">${media?`<img loading="lazy" src="${media.photos[0]}" alt="" onerror="this.hidden=true" />`:exIcon(ex)}</div><div class="exbody"><h3>${esc(ex.name)}</h3><p>${esc(tagCat(ex))} · ${ex.sets} ${ex.sets===1?'série':'séries'} · ${esc(ex.dose)} · ${esc(LABELS.gear[ex.gear])}</p><div class="row wrap">${withButton?`<button class="linklike" data-action="exercise" data-id="${ex.id}">Ver execução e cuidados →</button>`:`<span class="small muted">${esc(ex.why)}</span>`}</div></div></div>`;}
function recent(days){const since=new Date();since.setHours(0,0,0,0);since.setDate(since.getDate()-(days-1));return state.history.filter(s=>{const d=new Date(s.date+'T12:00:00');return !Number.isNaN(d.valueOf()) && d>=since;});}
function currentTip(){if(state.profile.readiness<=1)return 'Energia muito baixa: priorize repouso; evite treinos intensos.';if(state.profile.readiness===2)return 'Energia reduzida: mobilidade opcional e recuperação; evite treinos pesados.';return 'Treine com controle: deixe dias de recuperação entre sessões intensas.';}
function latestHistory(limit=6){return [...state.history].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,limit).map(s=>`<div class="history-item"><div class="history-symbol">${s.type==='bjj'?'🥋':'◆'}</div><div class="meta"><h4>${s.type==='bjj'?'Jiu-jitsu':'Preparação física'} · ${esc(s.title||'Treino')}</h4><p>${fmtDate(s.date)} · ${Number(s.duration)||0} min ${s.type==='bjj'?`· ${Number(s.rounds)||0} rolas`:''} · esforço ${esc(s.rpe||'—')}/10</p>${s.note?`<div class="small muted">${esc(s.note).slice(0,240)}</div>`:''}</div></div>`).join('')||'<div class="empty">Nenhum treino registrado ainda.</div>';}

function renderHome(){
 const week=recent(7),bjj=week.filter(s=>s.type==='bjj'),phys=week.filter(s=>s.type==='fisico');
 const pname=state.profile.name.trim().split(' ')[0]||'atleta';
 const load=weeklyLoad(state.history);
 const p=state.profile;
 return `${header('Seu espaço de evolução',`${greeting()}, <span>${esc(pname)}.</span>`,'Calistenia, força e mobilidade aplicadas ao seu jiu-jitsu. Um passo de cada vez.')}
 <div class="grid">
  <div class="span-8"><section class="card hero"><span class="badge">SEU PRÓXIMO PASSO</span><h2>${p.readiness<=2?'Hoje, priorize a recuperação.':'Construa força que aparece no tatame.'}</h2><p>${p.readiness<=2?'O plano será ajustado para mobilidade leve e descanso.':'Treinos pensados para seu nível, equipamento e estilo de jogo, sem ignorar a recuperação.'}</p><div class="row wrap"><button class="btn" data-action="navigate" data-to="plano">Montar meu treino →</button><button class="btn secondary" data-action="navigate" data-to="diario">Registrar rola</button></div></section></div>
  <div class="span-4"><section class="card"><div class="eyebrow">Como está sua energia?</div><h2 class="card-title" style="margin-top:10px">Prontidão de hoje</h2><p class="small muted">Informe como se sente antes de treinar.</p><div class="field"><label for="readiness">Energia percebida: <strong id="readiness-text">${p.readiness}/5</strong></label><input id="readiness" type="range" min="1" max="5" step="1" value="${p.readiness}" aria-label="Energia de hoje" /></div><div class="note ${p.readiness<=2?'warn':''}" style="margin-top:15px" id="readiness-note">${currentTip()}</div></section></div>
  <div class="span-4"><div class="stat"><div class="eyebrow">Últimos 7 dias</div><div class="kpi">${bjj.length}</div><div class="kpi-label">Treinos de jiu-jitsu</div></div></div>
  <div class="span-4"><div class="stat"><div class="eyebrow">Últimos 7 dias</div><div class="kpi">${phys.length}</div><div class="kpi-label">Sessões físicas</div></div></div>
  <div class="span-4"><div class="stat"><div class="eyebrow">Últimos 7 dias</div><div class="kpi">${week.reduce((sum,s)=>sum+Number(s.duration||0),0)}</div><div class="kpi-label">Minutos totais registrados</div></div></div>
  <div class="span-12">${gamificationCard()}</div>
 <div class="span-12">${section('Sua rotina',`<p class="small muted">Organize lembretes de exercícios pelo Google Agenda e avisos de hidratação enquanto o app estiver aberto.</p><button class="btn secondary small-btn" data-action="navigate" data-to="rotina">Configurar lembretes →</button>`)}</div>
 <div class="span-12">${section('Suas progressões',`<div class="row between wrap"><div><strong>${skillCompleted(state.skills)} etapas registradas</strong><p class="small muted">Seis trilhas para desenvolver força, quadril, pegada e controle.</p></div><button class="btn secondary small-btn" data-action="navigate" data-to="habilidades">Ver minhas habilidades →</button></div>`)}</div>
  <div class="span-7">${section('Seu perfil atual',`<div class="pill-row">${chip(LABELS.style[p.style])}${chip(LABELS.goal[p.goal])}${chip(LABELS.level[p.level])}${chip(LABELS.gear[p.equipment])}</div><p class="small muted">O plano é montado a partir destas informações. Você pode alterá-las quando quiser.</p><button class="btn secondary small-btn" data-action="navigate" data-to="ajustes">Ajustar meu perfil</button>`)}</div>
  <div class="span-5">${section('Histórico recente',latestHistory(3)+`<button class="btn ghost small-btn" data-action="navigate" data-to="evolucao" style="margin-top:12px">Ver evolução →</button>`)}</div>
 </div>${load.high?`<div class="note warn" style="margin-top:14px">Nos últimos 7 dias: ${load.bjj} treinos de BJJ, ${load.minutes} minutos, ${load.hard} intensos (RPE 8–10). Seu plano sugere no máximo duas sessões físicas; ajuste com orientação.</div>`:``}<p class="small muted" style="margin-top:18px">Atenção: fadiga incomum, dor intensa, falta de ar ou tontura exigem interromper o exercício e avaliar a situação. O aplicativo não substitui avaliação profissional.</p>`;
}

function renderPlan(){
 if(state.workout)return renderWorkout();
 const p=state.profile, plan=currentPlan(), load=weeklyLoad(state.history);
 const dayCards=plan.days.map((d,i)=>`<div class="session-card"><div class="row between" style="align-items:flex-start"><div class="row"><div class="session-count">${String.fromCharCode(65+i)}</div><div><h3>${esc(d.title)}</h3><p class="small muted" style="margin:3px 0">${esc(d.subtitle)}</p></div></div><span class="badge ${plan.recovery?'orange':'gray'}">${d.items.length} exercícios</span></div><div class="divider"></div>${d.items.map(ex=>exRow(ex)).join('')}<button class="btn" data-action="startWorkout" data-index="${i}">${plan.recovery?'Registrar sessão leve':'Iniciar sessão'} →</button></div>`).join('');
 return `${header('Planejamento','Seu <span>plano de treino.</span>','Treinos indicativos, ajustados ao tipo de jogo, ao nível e aos recursos disponíveis.')}
 <div class="grid"><div class="span-4"><section class="card"><div class="eyebrow">Configuração</div><h2 class="card-title" style="margin-top:10px">${esc(LABELS.style[p.style])}</h2><p class="small muted">${esc(LABELS.goal[p.goal])} · ${esc(LABELS.level[p.level])}</p><div class="divider"></div><div class="stack small"><div class="row between"><span class="muted">Equipamentos</span><strong>${esc(LABELS.gear[p.equipment])}</strong></div><div class="row between"><span class="muted">Sessões sugeridas</span><strong>${plan.days.length}${plan.recovery?' leve':''}</strong></div><div class="row between"><span class="muted">Energia informada</span><strong>${p.readiness}/5</strong></div></div><div class="divider"></div><button class="btn secondary" data-action="navigate" data-to="ajustes">Editar perfil</button></section><div class="note ${plan.recovery?'warn':''}" style="margin-top:14px">${esc(plan.why)} ${p.caution?'Ativada a preferência de cautela para lombar/quadril.':''}</div></div>
 <div class="span-8">${load.high?`<div class="note warn">Carga de BJJ registrada como elevada pelos critérios simples do app (${load.bjj} aulas, ${load.minutes} min, ${load.hard} intensas em 7 dias). A indicação foi reduzida para até 2 sessões, sem substituir orientação individual.</div>`:``}${dayCards}</div></div><p class="small muted">Sugestão geral: organize as sessões físicas em dias que permitam recuperação do jiu-jitsu. Os exercícios são exemplos educativos, não prescrição individual.</p>`;
}
function activeWorkoutDay(){
 const w=state.workout;if(!w)return null;
 if(w.day&&Array.isArray(w.day.ids)){const items=w.day.ids.map(id=>BY_ID[id]).filter(Boolean);return items.length?{title:w.day.title,items}:null;}
 return currentPlan().days[w.index]||null;
}
function renderWorkout(){
 const work=state.workout,day=activeWorkoutDay();
 if (!day) {state.workout=null;save();return renderPlan();}
 const done=Object.values(work.completed||{}).reduce((a,b)=>a+Number(b||0),0),total=day.items.reduce((a,e)=>a+e.sets,0);
 return `${header('Sessão em andamento','Treino <span>em execução.</span>',esc(day.title))}
 <button class="back" data-action="leaveWorkout">← Voltar ao início (mantém sessão)</button>
 <div class="grid"><div class="span-8"><section class="card"><div class="row between"><h2 class="section-title">Cronômetro da sessão</h2><span class="badge">TEMPO REAL</span></div>
 <div class="timer-face" id="work-clock">00:00</div><p class="timer-caption" id="work-clock-label">Tempo de treino em andamento</p>
 <div class="timer-controls"><button class="btn secondary small-btn" data-action="workPause" id="work-pause">Pausar</button><button class="btn ghost small-btn" data-action="workResume">Retomar</button><button class="btn secondary small-btn" data-action="restStart">Descanso de 60 s</button><button class="btn ghost small-btn" data-action="restStop">Encerrar descanso</button></div>
 <p id="rest-countdown" class="small muted" style="margin-top:11px;text-align:center">Pausa opcional entre séries.</p>
 <div class="divider"></div><div class="row between"><h2 class="section-title">Checklist de séries</h2><span class="badge">${done}/${total} séries</span></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,done/Math.max(1,total)*100)}%"></div></div><p class="small muted">Marque as séries concluídas. A qualidade do movimento vale mais que o número de repetições.</p>
 ${day.items.map((ex,i)=>`<div class="session-step"><div class="exicon">${exIcon(ex)}</div><div class="exbody"><h3>${esc(ex.name)}</h3><p>${ex.sets} ${ex.sets===1?'série':'séries'} de ${esc(ex.dose)}</p><div class="count-pill"><button aria-label="Retirar série de ${esc(ex.name)}" data-action="setMinus" data-index="${i}">−</button><output id="sets-${i}">${work.completed?.[i]||0}</output><button aria-label="Adicionar série de ${esc(ex.name)}" data-action="setPlus" data-index="${i}">+</button><span class="small muted">de ${ex.sets} séries</span><button class="linklike" data-action="exercise" data-id="${ex.id}">Ver técnica</button></div></div></div>`).join('')}
 <div class="form-grid" style="margin-top:18px"><div class="field"><label for="work-duration">Tempo total (minutos)</label><input type="number" id="work-duration" min="1" max="300" value="${Math.max(1,Math.min(300,Math.ceil(activeMs()/60000)))}" required></div><div class="field"><label for="work-rpe">Esforço percebido</label><select id="work-rpe">${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${i===5?'selected':''}>${i+1}/10</option>`).join('')}</select></div></div><div class="field" style="margin-top:12px"><label for="work-notes">Observações do treino</label><textarea id="work-notes" placeholder="Como foi? Algum desconforto ou dificuldade?"></textarea></div><div class="session-actions"><button class="btn" data-action="finishWorkout">Salvar sessão</button><button class="btn ghost" data-action="cancelWorkout">Cancelar sessão</button></div></section></div><div class="span-4">${section('Orientações',`<p class="small muted">Realize movimentos de forma controlada. Utilize pausas conforme necessidade e evite falhar deliberadamente em todas as séries.</p><div class="note warn">Em caso de dor aguda, tontura, falta de ar incomum ou mal-estar, interrompa o treino. Não registre exercício não realizado como concluído.</div>`)}</div></div>`;
}
function renderExerciseDetail(ex){return `<button class="back" data-action="backExercise">← Voltar</button>${header('Biblioteca de movimentos',`${esc(ex.name)}`,'Descrição educativa de execução e atenção à técnica.')}
 <div class="grid"><div class="span-7">${section('Como executar',`${imagesHtml(ex)}${bjjDiagram(ex)}${visualGuide(ex)}${!remoteImages(ex)&&!bjjDiagram(ex)&&!visualGuide(ex)?`<div class="note warn" style="margin-bottom:13px">Ainda não existe demonstração visual verificada deste movimento. Não execute apenas pela descrição escrita: peça orientação ao professor ou treinador.</div>`:""}<div class="pill-row">${chip(tagCat(ex))}${chip(LABELS.gear[ex.gear])}${chip('Nível '+(ex.level===1?'básico':ex.level===2?'intermediário':'avançado'))}</div><p class="lead">${esc(ex.why)}</p><ol style="padding-left:22px">${ex.steps.map(s=>`<li style="margin:10px 0">${esc(s)}</li>`).join('')}</ol><div class="note warn"><strong>Atenção:</strong> ${esc(ex.caution)}</div>`)}</div><div class="span-5">${section('Dose inicial sugerida',`<div class="kpi">${ex.sets} <span style="font-size:15px;font-weight:650">séries</span></div><p>${esc(ex.dose)}</p><p class="small muted">Ajuste conforme a técnica, esforço e recuperação. Essa dose não é individualizada.</p>`)}</div></div>`;}
function renderCatalogList(){
 const q=search.trim().toLocaleLowerCase('pt-BR');const found=EXERCISES.filter(e=>(filter==='todos'||e.category===filter) && (e.name.toLocaleLowerCase('pt-BR').includes(q)||e.focus.join(' ').includes(q)||e.why.toLocaleLowerCase('pt-BR').includes(q)));
 return `<div class="row between"><span class="small muted">${found.length} exercícios encontrados</span><span class="badge gray">Catálogo próprio</span></div>${found.map(e=>exRow(e)).join('')||'<div class="empty">Nenhum exercício corresponde à pesquisa.</div>'}`;
}
function renderExercises(){if(selectedExercise)return renderExerciseDetail(BY_ID[selectedExercise]);return `${header('Biblioteca de movimentos','Cada exercício tem <span>um propósito.</span>','Fotos de referência quando disponíveis, instruções e cuidados. Drills sem imagem verificada são identificados.')}
 <section class="card"><div class="form-grid"><div class="field"><label for="search-ex">Buscar exercício</label><input id="search-ex" type="search" placeholder="Ex.: pegada, prancha, quadril..." value="${esc(search)}" autocomplete="off"></div><div class="field"><label for="filter-ex">Tipo de exercício</label><select id="filter-ex"><option value="todos">Todas as categorias</option>${options(LABELS.category,filter)}</select></div></div><div class="divider"></div><div id="catalog-list">${renderCatalogList()}</div></section>`;}

function timerHtml(){return `<section class="card" id="timer-card"><div class="row between"><div><div class="eyebrow">Timer BJJ</div><h2 class="card-title" style="margin-top:7px">Rounds e descanso</h2></div><span class="badge gray" id="timer-stage">PRONTO</span></div><div class="form-grid" style="margin:12px 0"><div class="field"><label for="round-min">Duração de cada round</label><select id="round-min">${[2,3,4,5,6,8,10].map(v=>`<option value="${v}" ${v===5?'selected':''}>${v} min</option>`).join('')}</select></div><div class="field"><label for="rest-sec">Descanso entre rounds</label><select id="rest-sec">${[15,30,45,60,90,120].map(v=>`<option value="${v}" ${v===60?'selected':''}>${v} s</option>`).join('')}</select></div><div class="field"><label for="round-count">Quantidade de rounds</label><select id="round-count">${[1,2,3,4,5,6,8,10].map(v=>`<option value="${v}" ${v===5?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Áudio</label><div class="field-output small">Aviso sonoro quando permitido</div></div></div><div class="timer-face" id="timer-face">05:00</div><div class="timer-caption" id="timer-caption">Round 1 de 5</div><div class="timer-controls" style="margin-top:20px"><button class="btn" data-action="timerStart" id="timer-start">Iniciar</button><button class="btn secondary" data-action="timerPause">Pausar</button><button class="btn ghost" data-action="timerReset">Reiniciar</button></div><p class="tiny muted" style="margin-top:17px">O cronômetro usa o relógio do aparelho para compensar atrasos de tela; o som pode não funcionar com o navegador em segundo plano.</p></section>`;}
function renderDiary(){return `${header('Jiu-jitsu no cotidiano','Seu <span>diário de tatame.</span>','Registre aulas, rolas, temas e esforço. Depois o app conecta esse volume aos treinos físicos.')}
 <div class="grid"><div class="span-6"><section class="card"><h2 class="section-title">Registrar treino de BJJ</h2><form id="bjj-form" class="stack"><div class="form-grid"><div class="field"><label for="bjj-date">Data</label><input id="bjj-date" name="date" type="date" value="${isoLocalDate()}" required></div><div class="field"><label for="bjj-duration">Duração em minutos</label><input id="bjj-duration" name="duration" type="number" min="1" max="300" value="60" required></div><div class="field"><label for="bjj-rounds">Quantidade de rolas</label><input id="bjj-rounds" name="rounds" type="number" min="0" max="30" value="3" required></div><div class="field"><label for="bjj-rpe">Intensidade percebida (1 a 10)</label><select id="bjj-rpe" name="rpe">${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${i===5?'selected':''}>${i+1}/10</option>`).join('')}</select></div></div><div class="field"><label for="bjj-focus">Tema principal</label><select id="bjj-focus" name="focus"><option>Guarda e raspagens</option><option>Passagem de guarda</option><option>Quedas</option><option>Defesas e fugas</option><option>Finalizações</option><option>Treino livre</option></select></div><div class="field"><label for="bjj-note">Anotações técnicas</label><textarea id="bjj-note" name="note" maxlength="1000" placeholder="O que funcionou? O que gostaria de melhorar?"></textarea></div><button class="btn" type="submit">Salvar treino de jiu-jitsu</button></form></section></div>
 <div class="span-6">${timerHtml()}</div><div class="span-12">${section('Seus treinos recentes',latestHistory(12))}</div></div>`;}
function weeksChart(){
 const now=new Date();now.setHours(12,0,0,0);const day=now.getDay();now.setDate(now.getDate()-(day===0?6:day-1));const weeks=[];
 for(let i=5;i>=0;i--){const start=new Date(now);start.setDate(start.getDate()-i*7);const end=new Date(start);end.setDate(end.getDate()+7);const total=state.history.filter(s=>{const d=new Date(s.date+'T12:00:00');return d>=start && d<end;}).reduce((a,s)=>a+(Number(s.duration)||0),0);weeks.push({label:fmtDate(isoLocalDate(start)),total});}
 const max=Math.max(30,...weeks.map(x=>x.total));return `<div class="bar-plot">${weeks.map(w=>`<div class="bar-col"><span class="tiny muted">${w.total?`${w.total}m`:''}</span><div class="bar" style="height:${Math.max(3,(w.total/max)*117)}px" title="${w.total} minutos"></div><small>${w.label}</small></div>`).join('')}</div>`;
}
function renderProgress(){const stats=summarize(state.history),week=recent(7);const physical=state.history.filter(s=>s.type==='fisico');const completed=physical.reduce((n,s)=>n+(s.items||[]).reduce((k,item)=>k+(Number(item.done)||0),0),0);return `${header('Acompanhe sua jornada','Evolução <span>sem achismo.</span>','Aqui você acompanha o volume registrado. Progresso técnico no tatame também depende de prática e orientação.')}
 <div class="grid"><div class="span-3"><div class="stat"><div class="kpi">${stats.bjj}</div><div class="kpi-label">Treinos BJJ · 30 dias</div></div></div><div class="span-3"><div class="stat"><div class="kpi">${stats.physical}</div><div class="kpi-label">Treinos físicos · 30 dias</div></div></div><div class="span-3"><div class="stat"><div class="kpi">${stats.minutes}</div><div class="kpi-label">Minutos · 30 dias</div></div></div><div class="span-3"><div class="stat"><div class="kpi">${stats.rounds}</div><div class="kpi-label">Rolas · 30 dias</div></div></div>
 <div class="span-7">${section('Volume nas últimas 6 semanas',weeksChart()+`<div class="row between" style="margin-top:18px"><span class="small muted">Tempo registrado: treinos físicos + BJJ</span><span class="badge gray">Minutos</span></div>`)}</div>
 <div class="span-5">${section('Resumo da prática',`<div class="stack"><div class="result"><div class="muted small">Séries físicas registradas (total)</div><strong style="font-size:28px">${completed}</strong></div><div class="result"><div class="muted small">Dias com registros nos últimos 7 dias</div><strong style="font-size:28px">${new Set(week.map(s=>s.date)).size}</strong></div></div><p class="small muted">Acompanhe regularidade sem transformar descanso em competição.</p>`)}</div>
 <div class="span-12">${section('Evolução por habilidade',`<p class="small muted">${skillCompleted(state.skills)} etapas registradas em ${TRACKS.length} trilhas. Registre domínio sem pular a técnica.</p><button class="btn secondary small-btn" data-action="navigate" data-to="habilidades">Abrir progressões →</button>`)}</div><div class="span-12">${section('Histórico completo',latestHistory(100))}</div></div>`;}
function renderSkills(){
 const done=skillCompleted(state.skills),total=TRACKS.reduce((a,t)=>a+t.stages.length,0),profile=state.profile;
 if(selectedTrack){
  const track=TRACKS.find(t=>t.id===selectedTrack);if(!track){selectedTrack=null;return renderSkills();}
  const ix=skillIndex(state.skills,track),stage=track.stages[ix],ex=stage?BY_ID[stage.id]:null;
  const allowed=ex&&stageAllowed(ex,profile);
  return `<button class="back" data-action="skillsBack">← Todas as trilhas</button>${header('Habilidades para o tatame',esc(track.title),esc(track.subtitle))}
  <div class="grid"><div class="span-7"><section class="card"><h2 class="section-title">Sua sequência</h2><div class="skill-steps">${track.stages.map((s,i)=>`<div class="skill-step ${i<ix?'done':i===ix?'current':''}"><span class="skill-count">${i<ix?'✓':i+1}</span><div><strong>${esc(BY_ID[s.id].name)}</strong><p class="small muted">${i<ix?'Etapa registrada':i===ix?'Etapa atual':'Próxima etapa'} · ${esc(LABELS.gear[BY_ID[s.id].gear])}</p></div>${i===ix?'<span class="badge">AGORA</span>':''}</div>`).join('')}</div></section></div>
  <div class="span-5"><section class="card"><h2 class="section-title">${ix>=track.stages.length?'Trilha concluída':'Etapa atual'}</h2>${stage?`<p><strong>${esc(ex.name)}</strong></p><p class="small muted">Meta orientativa: ${esc(stage.criterion)}</p><p class="small muted">Séries registradas deste exercício: ${recordedSets(state.history,ex.id)}</p>${allowed?`<div class="stack"><label class="toggle-line"><input type="checkbox" id="skill-check1"> <span>Completei a meta com técnica controlada.</span></label><label class="toggle-line"><input type="checkbox" id="skill-check2"> <span>Não tive dor nem perda de controle.</span></label><button class="btn" data-action="skillNext" data-id="${track.id}">Registrar domínio desta etapa</button></div>`:`<div class="note warn">Esta etapa não está disponível com seu nível, equipamentos ou opção de cautela atuais. Ajuste o perfil e priorize segurança.</div>`}<button class="btn ghost small-btn" data-action="exercise" data-id="${ex.id}">Ver execução →</button>`:`<p>Você registrou todas as etapas desta trilha. Continue treinando com qualidade, sem obrigação de aumentar dificuldade.</p>`}${ix>0?`<div class="divider"></div><button class="btn ghost small-btn" data-action="skillBackStep" data-id="${track.id}">Corrigir etapa anterior</button>`:''}</section></div></div>
  <p class="small muted" style="margin-top:18px">Estas metas são referências educativas, não avaliação de capacidade, técnica de luta ou diagnóstico. Progredir requer domínio, ausência de sintomas e recuperação suficiente.</p>`;
 }
 return `${header('Seu mapa de habilidades','Progrida com <span>critério.</span>','Evolução por qualidade de movimento. Avançar é uma decisão consciente, nunca automática.')}
 <section class="card"><div class="row between"><div><div class="eyebrow">Seu progresso</div><strong>${done} de ${total} etapas registradas</strong></div><span class="badge gray">v0.2</span></div><div class="progress-track" style="margin-top:12px"><div class="progress-fill" style="width:${Math.round(100*done/total)}%"></div></div><p class="tiny muted">Metas não são obrigatórias nem representam graduação no jiu-jitsu.</p></section><div class="grid" style="margin-top:14px">${TRACKS.map(t=>{const ix=skillIndex(state.skills,t),stage=t.stages[ix],ex=stage?BY_ID[stage.id]:null;return `<div class="span-6"><section class="card skill-card"><span class="badge gray">${ix}/${t.stages.length} etapas</span><h2 class="card-title" style="margin-top:10px">${esc(t.title)}</h2><p class="small muted">${esc(t.subtitle)}</p><p><strong>Agora:</strong> ${ex?esc(ex.name):'Trilha registrada'}</p><button class="btn secondary small-btn" data-action="skillView" data-id="${t.id}">Abrir trilha →</button></section></div>`;}).join('')}</div>`;
}
function renderSettings(){const p=state.profile;return `${header('Personalização','Seu perfil, <span>suas regras.</span>','Altere o objetivo a qualquer momento. Seus registros não dependem de conta ou servidor.')}
 <div class="grid"><div class="span-7"><section class="card"><h2 class="section-title">Perfil do atleta</h2><form id="profile-form" class="stack"><div class="form-grid"><div class="field"><label for="p-name">Como quer ser chamado?</label><input id="p-name" name="name" value="${esc(p.name)}" maxlength="48" placeholder="Ex.: Atleta"></div><div class="field"><label for="p-belt">Faixa no jiu-jitsu</label><select id="p-belt" name="belt">${options({branca:'Branca',azul:'Azul',roxa:'Roxa',marrom:'Marrom',preta:'Preta',outro:'Outra / não pratico'},p.belt)}</select></div><div class="field"><label for="p-style">Meu estilo de jogo</label><select id="p-style" name="style">${options(LABELS.style,p.style)}</select></div><div class="field"><label for="p-goal">Meu objetivo principal</label><select id="p-goal" name="goal">${options(LABELS.goal,p.goal)}</select></div><div class="field"><label for="p-level">Nível físico atual</label><select id="p-level" name="level">${options(LABELS.level,p.level)}</select></div><div class="field"><label for="p-equipment">O que tenho disponível</label><select id="p-equipment" name="equipment">${options(LABELS.gear,p.equipment)}</select></div><div class="field"><label for="p-days">Treinos físicos sugeridos/semana</label><select id="p-days" name="days"><option value="2" ${p.days===2?'selected':''}>2 dias</option><option value="3" ${p.days===3?'selected':''}>3 dias</option></select></div><div class="field"><label for="p-readiness">Energia de hoje (1 a 5)</label><select id="p-readiness" name="readiness">${[1,2,3,4,5].map(v=>`<option value="${v}" ${p.readiness===v?'selected':''}>${v} / 5</option>`).join('')}</select></div></div><label class="toggle-line"><input type="checkbox" name="caution" ${p.caution?'checked':''}> <span>Aplicar cautela extra para movimentos que podem sobrecarregar lombar ou quadril. Essa opção não substitui avaliação de saúde.</span></label><button class="btn" type="submit">Salvar meu perfil</button></form></section></div>
 <div class="span-5"><section class="card"><h2 class="section-title">Dados e instalação</h2><p class="small muted">Tudo fica neste dispositivo, no armazenamento do navegador. Apagar os dados do navegador pode apagar o histórico.</p>${memoryOnly?'<div class="note alert">Armazenamento indisponível: seus dados podem não persistir. Exporte agora um backup.</div>':''}<div class="stack" style="margin:17px 0"><button class="btn secondary" data-action="navigate" data-to="rotina">Configurar lembretes e pontos</button><button class="btn secondary" data-action="export">Baixar backup JSON</button><button class="btn secondary" data-action="csv">Exportar histórico CSV</button><label class="btn ghost" for="file-import" style="text-align:center;cursor:pointer">Restaurar backup</label><input id="file-import" type="file" accept="application/json,.json" class="hide"/><button class="btn ghost" data-action="install">Instalar no Android</button></div><div class="divider"></div><p class="tiny muted"><a href="https://repdb.co" target="_blank" rel="noopener noreferrer">Exercise data by RepDB (repdb.co)</a> — ilustrações licenciadas para uso no aplicativo.</p><button class="btn danger small-btn" data-action="clear">Apagar todos os registros</button></section><div class="note warn" style="margin-top:14px"><strong>Privacidade:</strong> não há login, anúncios nem envio de registros. Ilustrações carregadas pelo navegador podem gerar requisições ao servidor RepDB. O arquivo de backup contém suas informações e deve ser guardado em local seguro.</div></div></div>`;}

function gamificationCard(){const g=gamification(state.history,state.skills,state.profile.days);return `<section class="card game-card"><div class="row between"><div><div class="eyebrow">Seu progresso de consistência</div><h2 class="card-title" style="margin-top:8px">🏅 ${esc(g.level)}</h2></div><div class="game-xp">${g.xp} <span>XP</span></div></div><div class="progress-track" style="margin-top:12px"><div class="progress-fill" style="width:${Math.round(g.progress*100)}%"></div></div><p class="small muted">${g.next?`Faltam ${g.next.xp-g.xp} XP para ${esc(g.next.name)}.`:'Você alcançou o nível mais alto atual.'} Meta da semana: ${g.currentWeekDays}/${g.weeklyGoal} dias registrados. Sem sequência obrigatória diária.</p><div class="row wrap"><span class="chip">🔥 ${g.streak} semanas consistentes</span><span class="chip">🏆 ${g.badges.length}/${AWARDS.length} medalhas</span><button class="btn secondary small-btn" data-action="navigate" data-to="rotina">Ver conquistas →</button></div></section>`;}
function renderRoutine(){const r=state.reminders||DEFAULT_REMINDERS,g=gamification(state.history,state.skills,state.profile.days),upcoming=calendarUrl(r);
 const days=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];return `${header('Consistência sem pressão','Seu <span>ritmo de evolução.</span>','Conquistas e lembretes são incentivos. Descanso e técnica sempre têm prioridade.')}
 <div class="grid"><div class="span-12">${gamificationCard()}</div><div class="span-7"><section class="card"><h2 class="section-title">Planejar lembretes</h2><p class="small muted">No app aberto, podemos avisar no horário escolhido. Para alertas com o app fechado, use o Google Agenda.</p>
 <form id="routine-form" class="stack"><label class="toggle-line"><input type="checkbox" name="enabled" ${r.enabled?'checked':''}><span>Ativar lembrete de treino no aplicativo aberto</span></label><div class="form-grid"><div class="field"><label for="r-time">Horário de treino</label><input id="r-time" name="time" type="time" required value="${esc(r.time)}"></div><div class="field"><label for="r-duration">Duração prevista</label><select name="duration">${[20,30,35,45,60,90].map(v=>`<option value="${v}" ${r.duration===v?'selected':''}>${v} minutos</option>`).join('')}</select></div></div><div><label class="small bold">Dias da semana</label><div class="weekday-row">${days.map((t,i)=>`<label class="weekday"><input type="checkbox" name="day" value="${i}" ${(r.days||[]).includes(i)?'checked':''}><span>${t}</span></label>`).join('')}</div></div>
 <div class="divider"></div><label class="toggle-line"><input type="checkbox" name="water" ${r.water?'checked':''}><span>Lembrar de fazer uma pausa para beber água, quando o aplicativo estiver aberto (opcional)</span></label><div class="field"><label for="r-water">Intervalo do lembrete de pausa</label><select name="waterInterval" id="r-water">${[120,180,240].map(v=>`<option value="${v}" ${r.waterInterval===v?'selected':''}>A cada ${v/60} horas, entre 8h e 22h</option>`).join('')}</select></div>
 <button class="btn" type="submit">Salvar lembretes</button></form><div class="divider"></div>
 <div class="row wrap"><button class="btn secondary small-btn" data-action="calendar">Criar no Google Agenda</button><button class="btn ghost small-btn" data-action="calendarIcs">Baixar agenda semanal (.ics)</button><button class="btn ghost small-btn" data-action="notifications">Permitir avisos com app aberto</button></div>
 <p class="tiny muted">O link do Google Agenda cria um evento. Para repetir, selecione “repetir semanalmente” no Google Agenda; o arquivo ICS inclui repetição nos dias escolhidos e aviso sugerido de 15 minutos, sujeito ao calendário usado.</p>
 ${!upcoming?'<div class="note warn">Escolha ao menos um dia da semana e salve os lembretes.</div>':''}
 </section></div>
 <div class="span-5"><section class="card"><h2 class="section-title">Medalhas</h2><div class="award-grid">${AWARDS.map(b=>{const ok=g.badges.some(a=>a.id===b.id);return `<div class="award ${ok?'unlocked':'locked'}"><div class="award-icon">${b.icon}</div><div><strong>${esc(b.name)}</strong><p class="tiny muted">${esc(b.desc)}</p></div><span class="badge ${ok?'':'gray'}">${ok?'Feita':'Pendente'}</span></div>`;}).join('')}</div></section></div></div>
 <p class="small muted" style="margin-top:16px">Os XP são calculados a partir das sessões físicas, treinos de BJJ e etapas registradas. Não há perda de XP por dias de descanso. Não associe metas a beber quantidades excessivas de água.</p>`;}
const formatClock=ms=>{const secs=Math.floor(Math.max(0,ms)/1000);return String(Math.floor(secs/60)).padStart(2,'0')+':'+String(secs%60).padStart(2,'0');};
function activeMs(){const w=state.workout;if(!w)return 0;return Math.max(0,Number(w.elapsedMs)||0)+(w.paused?0:Math.max(0,Date.now()-Number(w.resumeAt||w.startedAt||Date.now())));}
function sessionTick(){if(!state.workout)return;const w=state.workout,clock=document.getElementById('work-clock');if(clock){clock.textContent=formatClock(activeMs());const label=document.getElementById('work-clock-label');if(label)label.textContent=w.paused?'Cronômetro pausado':'Cronômetro em andamento';const pause=document.getElementById('work-pause');if(pause)pause.disabled=!!w.paused;const actualDuration=document.getElementById('work-duration');if(actualDuration&&!actualDuration.dataset.userEdited)actualDuration.value=String(Math.max(1,Math.min(300,Math.ceil(activeMs()/60000))));}
 const rest=document.getElementById('rest-countdown');if(rest){const left=Math.max(0,Number(w.restUntil||0)-Date.now());rest.textContent=left?'Descanso restante: '+formatClock(left):'Pausa opcional entre séries.';if(w.restUntil&&left===0){w.restUntil=0;save();notify('Descanso encerrado. Retome apenas quando estiver recuperado.');}}}
function reminderCheck(){const r=state.reminders;if(!r||!r.enabled&&!r.water)return;const now=new Date(),hr=now.getHours(),today=isoLocalDate(now);if(inQuietTime(hr))return;
 if(r.enabled&&(r.days||[]).includes(now.getDay())&&r.lastWorkout!==today){const [hh,mm]=String(r.time).split(':').map(Number);const m=hr*60+now.getMinutes()-(hh*60+mm);if(m>=0&&m<15){r.lastWorkout=today;save();notify('Seu horário de treino chegou. Confira como está sua energia hoje.');showRemind('Hora de treinar','Abra seu plano, respeitando a recuperação.');}}
 if(r.water){const step=Number(r.waterInterval)||180;const min=hr*60+now.getMinutes();const slot=Math.floor((min-8*60)/step);const key=today+'/'+slot;if(min>=8*60&&slot>=0&&Math.floor((min-8*60)%step)<3&&r.lastWater!==key){r.lastWater=key;save();notify('Pausa para hidratação, se precisar.');showRemind('Pausa para água','Faça uma pausa e hidrate-se conforme sua sede e atividade.');}}
}
async function showRemind(title,body){if(!state.reminders?.notify||typeof Notification==='undefined'||Notification.permission!=='granted')return;try{const reg=await navigator.serviceWorker?.ready;if(reg?.showNotification)await reg.showNotification(title,{body,icon:'./assets/icon-192.png',tag:'calistenia-bjj-reminder'});}catch{}}

function render(){document.querySelectorAll('[data-tab]').forEach(n=>{n.classList.toggle('selected',n.dataset.tab===(['habilidades','rotina'].includes(tab)?'evolucao':tab));n.setAttribute('aria-current',n.dataset.tab===(['habilidades','rotina'].includes(tab)?'evolucao':tab)?'page':'false');});content.innerHTML=tab==='inicio'?renderHome():tab==='plano'?renderPlan():tab==='exercicios'?renderExercises():tab==='diario'?renderDiary():tab==='evolucao'?renderProgress():tab==='habilidades'?renderSkills():tab==='rotina'?renderRoutine():renderSettings(); if(tab==='diario')syncTimerUI();}

// Temporizador resiste a atrasos de execução por meio de timestamps reais.
let timer={running:false,started:false,phase:'round',round:1,total:5,roundMs:300000,restMs:60000,remainingMs:300000,endAt:0,done:false};
let audioCtx;
function beep(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;audioCtx=audioCtx||new Audio();const oscillator=audioCtx.createOscillator(),gain=audioCtx.createGain();oscillator.type='sine';oscillator.frequency.value=740;gain.gain.value=.05;oscillator.connect(gain);gain.connect(audioCtx.destination);oscillator.start();oscillator.stop(audioCtx.currentTime+.16);if(navigator.vibrate)navigator.vibrate(100);}catch{}}
function timerSetup(){const r=Number(document.getElementById('round-min')?.value||5),rest=Number(document.getElementById('rest-sec')?.value||60),count=Number(document.getElementById('round-count')?.value||5);timer={running:false,started:false,phase:'round',round:1,total:count,roundMs:r*60000,restMs:rest*1000,remainingMs:r*60000,endAt:0,done:false};syncTimerUI();}
function timerTick(){if(!timer.running)return;let safety=0;while(timer.running&&Date.now()>=timer.endAt&&safety++<100){if(timer.phase==='round'){if(timer.round>=timer.total){timer.running=false;timer.done=true;timer.remainingMs=0;break;}timer.phase='rest';timer.endAt+=timer.restMs;}else{timer.phase='round';timer.round++;timer.endAt+=timer.roundMs;}beep();}if(timer.running)timer.remainingMs=Math.max(0,timer.endAt-Date.now());syncTimerUI();}
function syncTimerUI(){const face=document.getElementById('timer-face');if(!face)return;const r=timer.started?timer.remainingMs:Number(document.getElementById('round-min')?.value||5)*60000;const secs=Math.ceil(r/1000),m=String(Math.floor(secs/60)).padStart(2,'0'),s=String(secs%60).padStart(2,'0');face.textContent=`${m}:${s}`;face.classList.toggle('rest',timer.phase==='rest');document.getElementById('timer-stage').textContent=timer.done?'CONCLUÍDO':timer.started?(timer.phase==='round'?'ROUND':'DESCANSO'):'PRONTO';document.getElementById('timer-caption').textContent=timer.done?'Sessão finalizada':`Round ${timer.round} de ${timer.total}`;document.getElementById('timer-start').textContent=timer.running?'Executando...':timer.started?'Continuar':'Iniciar';document.getElementById('timer-start').disabled=timer.running||timer.done;}
setInterval(timerTick,250);
setInterval(sessionTick,350);
setInterval(reminderCheck,30000);

document.querySelector('.bottom-nav').addEventListener('click',e=>{const item=e.target.closest('[data-tab]');if(item)go(item.dataset.tab);});
document.getElementById('settings-shortcut').addEventListener('click',()=>go('ajustes'));
content.addEventListener('input',e=>{
 if(e.target.id==='search-ex'){search=e.target.value;const list=document.getElementById('catalog-list');if(list)list.innerHTML=renderCatalogList();}
 if(e.target.id==='readiness'){document.getElementById('readiness-text').textContent=e.target.value+'/5';}
 if(e.target.id==='work-duration')e.target.dataset.userEdited='true';
});
content.addEventListener('change',e=>{
 if(e.target.id==='filter-ex'){filter=e.target.value;document.getElementById('catalog-list').innerHTML=renderCatalogList();}
 if(e.target.id==='readiness'){state.profile.readiness=Number(e.target.value);save();render();}
 if(e.target.id==='round-min'&&!timer.started){timerSetup();}
 if((e.target.id==='rest-sec'||e.target.id==='round-count')&&!timer.started){timerSetup();}
 if(e.target.id==='file-import'&&e.target.files[0]){const f=e.target.files[0];if(f.size>5_000_000){notify('Backup muito grande (máximo 5 MB).');return;}f.text().then(raw=>{let data;try{data=JSON.parse(raw)}catch{notify('Arquivo JSON inválido.');return;}if(!validateImport(data)){notify('Backup incompatível ou inválido.');return;}if(!confirm('Substituir o histórico e o perfil atuais por este backup?'))return;state={...freshState(),...data,profile:{...DEFAULT_PROFILE,...data.profile},reminders:normalizeReminders(data.reminders),workout:null};save();notify('Backup restaurado.');go('inicio');}).catch(()=>notify('Não foi possível ler o arquivo.'));}
});
content.addEventListener('submit',e=>{
 e.preventDefault();
 if(e.target.id==='routine-form'){
  const f=new FormData(e.target),days=f.getAll('day').map(Number),time=String(f.get('time')||'18:00'),duration=Number(f.get('duration')),waterInterval=Number(f.get('waterInterval'));
  if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)||days.some(n=>!Number.isInteger(n)||n<0||n>6)||!days.length){notify('Selecione ao menos um dia e um horário válido.');return;}
  state.reminders={...state.reminders,enabled:f.has('enabled'),water:f.has('water'),days,time,duration:Math.max(10,Math.min(180,duration||35)),waterInterval:[120,180,240].includes(waterInterval)?waterInterval:180,lastWorkout:'',lastWater:''};save();notify('Rotina salva. Para alertas com app fechado, use o Google Agenda.');render();return;
 }
 if(e.target.id==='profile-form'){
  const f=new FormData(e.target);state.profile={name:String(f.get('name')||'').trim().slice(0,48),belt:String(f.get('belt')),style:String(f.get('style')),goal:String(f.get('goal')),level:String(f.get('level')),equipment:String(f.get('equipment')),days:Math.min(3,Math.max(2,Number(f.get('days'))||2)),readiness:Math.min(5,Math.max(1,Number(f.get('readiness'))||3)),caution:f.has('caution')};save();notify('Perfil atualizado.');go('plano');
 }
 if(e.target.id==='bjj-form'){
  const f=new FormData(e.target),duration=Number(f.get('duration')),rounds=Number(f.get('rounds')),rpe=Number(f.get('rpe')),date=String(f.get('date'));
  if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||duration<1||duration>300||rounds<0||rounds>30||rpe<1||rpe>10){notify('Confira os dados do treino.');return;}
  const before=gamification(state.history,state.skills,state.profile.days).xp;state.history.push({id:crypto.randomUUID?.()||String(Date.now()),type:'bjj',date,duration,rounds,rpe,title:String(f.get('focus')).slice(0,80),note:String(f.get('note')||'').trim().slice(0,1000)});save();render();notify('BJJ registrado! +'+Math.max(0,gamification(state.history,state.skills,state.profile.days).xp-before)+' XP.');
 }
});

function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvCell(x){return '"'+String(x??'').replace(/^[\s]*[=+@-]/,'\'$&').replace(/"/g,'""')+'"';}
content.addEventListener('click',e=>{
 const btn=e.target.closest('[data-action]');if(!btn)return;const action=btn.dataset.action;
 if(action==='navigate'){if(btn.dataset.to==='habilidades')selectedTrack=null;go(btn.dataset.to);return;}
 if(action==='calendar'){const url=calendarUrl(state.reminders);if(!url){notify('Configure os dias e o horário antes.');return;}window.open(url,'_blank','noopener,noreferrer');return;}
 if(action==='calendarIcs'){const ics=calendarIcs(state.reminders);if(!ics){notify('Configure os dias e o horário antes.');return;}download('calistenia-bjj-treinos.ics',ics,'text/calendar;charset=utf-8');notify('Arquivo de calendário gerado.');return;}
 if(action==='notifications'){if(typeof Notification==='undefined'){notify('Este navegador não oferece notificações neste contexto. Use a Agenda.');return;}Notification.requestPermission().then(p=>{state.reminders.notify=p==='granted';save();notify(p==='granted'?'Avisos permitidos com app aberto.':'Notificações não foram permitidas. Use a Agenda.');}).catch(()=>notify('Não foi possível ativar os avisos.'));return;}
 if(action==='workPause'){const w=state.workout;if(w&&!w.paused){w.elapsedMs=activeMs();w.paused=true;save();sessionTick();}return;}
 if(action==='workResume'){const w=state.workout;if(w&&w.paused){w.resumeAt=Date.now();w.paused=false;save();sessionTick();}return;}
 if(action==='restStart'){const w=state.workout;if(w){w.restUntil=Date.now()+60000;save();sessionTick();}return;}
 if(action==='restStop'){const w=state.workout;if(w){w.restUntil=0;save();sessionTick();}return;}
 if(action==='skillView'){selectedTrack=btn.dataset.id;render();window.scrollTo(0,0);return;}
 if(action==='skillsBack'){selectedTrack=null;render();window.scrollTo(0,0);return;}
 if(action==='skillNext'){
  const track=TRACKS.find(t=>t.id===btn.dataset.id);if(!track)return;const ix=skillIndex(state.skills,track),ex=BY_ID[track.stages[ix]?.id];
  if(!ex||!stageAllowed(ex,state.profile)){notify('Esta etapa não está disponível neste perfil.');return;}
  if(!document.getElementById('skill-check1')?.checked||!document.getElementById('skill-check2')?.checked){notify('Confirme os dois critérios antes de avançar.');return;}
  if(!confirm('Registrar domínio desta etapa? Esta marcação é manual e não equivale a avaliação profissional.'))return;
  state.skills=state.skills||{};state.skills[track.id]=ix+1;save();render();notify('Etapa registrada! +40 XP.');return;
 }
 if(action==='skillBackStep'){
  const track=TRACKS.find(t=>t.id===btn.dataset.id);if(!track)return;const ix=skillIndex(state.skills,track);
  if(ix>0&&confirm('Voltar uma etapa desta trilha? Os treinos já registrados continuarão salvos.')){state.skills[track.id]=ix-1;save();render();}return;
 }

 if(action==='exercise'){exerciseReturn=tab;selectedExercise=btn.dataset.id;tab='exercicios';render();window.scrollTo(0,0);return;}
 if(action==='backExercise'){selectedExercise=null;go(exerciseReturn);return;}
 if(action==='startWorkout'){const idx=Number(btn.dataset.index),day=currentPlan().days[idx];if(!day)return;state.workout={index:idx,day:{title:day.title,ids:day.items.map(e=>e.id)},startedAt:Date.now(),resumeAt:Date.now(),elapsedMs:0,paused:false,restUntil:0,completed:{}};save();render();window.scrollTo(0,0);return;}
 if(action==='leaveWorkout'){go('inicio');return;}
 if(action==='cancelWorkout'){if(confirm('Descartar este treino sem salvá-lo?')){state.workout=null;save();render();}return;}
 if(action==='setPlus'||action==='setMinus'){
  const i=Number(btn.dataset.index),ex=activeWorkoutDay()?.items[i];if(!ex)return;
  const prior=Number(state.workout.completed[i]||0),next=Math.min(ex.sets,Math.max(0,prior+(action==='setPlus'?1:-1)));state.workout.completed[i]=next;save();const count=document.getElementById(`sets-${i}`);if(count)count.textContent=String(next);const day=activeWorkoutDay(),done=Object.values(state.workout.completed).reduce((n,v)=>n+Number(v||0),0),total=day.items.reduce((n,e)=>n+e.sets,0);const progress=document.querySelector('.progress-fill');if(progress)progress.style.width=Math.min(100,done/Math.max(1,total)*100)+'%';const countBadge=document.querySelector('.card .badge');if(countBadge)countBadge.textContent=`${done}/${total} séries`;return;
 }
 if(action==='finishWorkout'){
  if(!state.workout)return;const day=activeWorkoutDay();if(!day)return;const dur=Number(document.getElementById('work-duration')?.value),rpe=Number(document.getElementById('work-rpe')?.value),note=String(document.getElementById('work-notes')?.value||'').trim().slice(0,1000);
  const items=day.items.map((ex,i)=>({id:ex.id,name:ex.name,done:Number(state.workout.completed[i]||0),planned:ex.sets,dose:ex.dose}));
  if(!items.some(item=>item.done>0)){notify('Marque pelo menos uma série realizada.');return;}
  const record={id:crypto.randomUUID?.()||String(Date.now()),type:'fisico',date:isoLocalDate(),title:day.title,duration:dur,rpe,note,items,elapsedSeconds:Math.floor(activeMs()/1000)};
  if(!validateSession(record)||rpe<1||rpe>10){notify('Informe duração válida de 1 a 300 minutos.');return;}
  const before=gamification(state.history,state.skills,state.profile.days).xp;state.history.push(record);state.workout=null;save();go('evolucao');notify('Sessão salva! +'+Math.max(0,gamification(state.history,state.skills,state.profile.days).xp-before)+' XP.');return;
 }
 if(action==='export'){download(`calistenia-bjj-backup-${isoLocalDate()}.json`,JSON.stringify({...state,workout:null},null,2),'application/json');notify('Arquivo de backup gerado.');return;}
 if(action==='csv'){const head=['Data','Tipo','Título','Minutos','Rolas','Esforço 1-10','Notas'];const rows=state.history.map(s=>[s.date,s.type,s.title,s.duration,s.rounds||0,s.rpe,s.note||'']);download(`calistenia-bjj-historico-${isoLocalDate()}.csv`,[head,...rows].map(a=>a.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');notify('Histórico CSV gerado.');return;}
 if(action==='clear'){if(confirm('Apagar TODOS os registros e o perfil deste navegador? Essa ação não pode ser desfeita sem backup.')){state=freshState();save();notify('Dados apagados neste navegador.');go('inicio');}return;}
 if(action==='install'){if(installPrompt){installPrompt.prompt();installPrompt.userChoice.finally(()=>installPrompt=null);}else{notify('No Android: abra pelo Chrome, menu ⋮ e escolha “Adicionar à tela inicial” ou “Instalar app”.');}return;}
 if(action==='timerStart'){if(!timer.started)timerSetup();timer.started=true;timer.running=true;timer.endAt=Date.now()+timer.remainingMs;try{audioCtx?.resume?.();}catch{}syncTimerUI();return;}
 if(action==='timerPause'){if(timer.running){timerTick();timer.remainingMs=Math.max(0,timer.endAt-Date.now());timer.running=false;syncTimerUI();}return;}
 if(action==='timerReset'){timerSetup();return;}
});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
if('serviceWorker' in navigator){let changed=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!changed){changed=true;location.reload();}});window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));}
render();
window.addEventListener('focus',()=>{sessionTick();reminderCheck();});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){sessionTick();reminderCheck();}});
